-- Reference/demo data exported from the project database.
-- COPY first targets temporary staging tables so this migration is safe on an existing development database.

CREATE TEMP TABLE seed_road_node ON COMMIT DROP AS
SELECT * FROM public.road_node WITH NO DATA;


SELECT id, geom_local, network_version, created_at, updated_at
FROM seed_road_node
ON CONFLICT (id) DO NOTHING;

DO $verify$
BEGIN
    IF EXISTS (
        SELECT id FROM seed_road_node
        EXCEPT
        SELECT id FROM public.road_node
    ) THEN
        RAISE EXCEPTION 'Failed to merge all seed rows into public.road_node';
    END IF;
END
$verify$;

ANALYZE public.road_node;

CREATE TEMP TABLE seed_road_edge ON COMMIT DROP AS
SELECT * FROM public.road_edge WITH NO DATA;


SELECT id, source, target, name, instruction, road_type, geom_local, length_m, speed_kmh, driving_cost_s, driving_reverse_s, walking_cost_s, walking_reverse_s, one_way, bridge, tunnel, access_car, access_walk, coordinate_status, status, network_version, created_at, updated_at, description
FROM seed_road_edge
ON CONFLICT (id) DO NOTHING;

DO $verify$
BEGIN
    IF EXISTS (
        SELECT id FROM seed_road_edge
        EXCEPT
        SELECT id FROM public.road_edge
    ) THEN
        RAISE EXCEPTION 'Failed to merge all seed rows into public.road_edge';
    END IF;
END
$verify$;

SELECT setval(
    pg_get_serial_sequence('public.road_edge', 'id'),
    COALESCE((SELECT max(id) FROM public.road_edge), 1),
    EXISTS (SELECT 1 FROM public.road_edge)
);

ANALYZE public.road_edge;
